-- title: Data quality
-- description: A deliberately messy customer list (duplicates, missing values, inconsistent spelling, impossible values) for data-quality investigations.
--
-- Tables: customers_raw
-- This file is read-only sample data for the SQL Lab. The app copies it into a
-- practice database, so your experiments never change this file.
-- Generated by tools/generate_datasets.py

PRAGMA foreign_keys = ON;

CREATE TABLE customers_raw (
    id          INTEGER PRIMARY KEY,
    first_name  TEXT,
    last_name   TEXT,
    email       TEXT,
    phone       TEXT,
    city        TEXT,
    country     TEXT,
    joined_on   TEXT,
    total_spend REAL
);

